mapper.select:
SELECT id, outcome, screen_agency, screen_time, screen_order, person_id, contacted
FROM tb_screen_collect
WHERE person_id = #{patientId}
  AND year = #{year}
  AND screen_type = #{screenType}
  AND deleted = 0
ORDER BY id DESC

SELECT chest_radiograph_code, chest_radiograph, photo_time AS screenTime, outcome, screen_order,person_id, id
FROM tb_screen_chest_radiograph
WHERE person_id = #{patientId}
  AND year = #{year}
  AND screen_type = #{screenType}
  AND deleted = 0
ORDER BY id DESC

SELECT electrocardiogram, screen_time, screen_order, person_id, id
FROM tb_screen_electrocardiogram
WHERE person_id = #{patientId}
  AND year = #{year}
  AND screen_type = #{screenType}
  AND deleted = 0
ORDER BY id DESC

SELECT screen_time, outcome, report, preventive_treatment, screen_order, person_id, id, treatment_program
FROM tb_screen_diagnosis
WHERE person_id = #{patientId}
  AND year = #{year}
  AND screen_type = #{screenType}
  AND deleted = 0
ORDER BY id DESC

SELECT id
FROM tb_screen_person
WHERE id_num = #{idNum}
  AND year = #{year}
  AND screen_type = #{screenType}
  AND deleted = 0

SELECT url, id
FROM tb_screen_images
WHERE person_id = #{personId}
  AND type = #{type}
  AND screen_order = #{screenOrder}
  AND year = #{year}
  AND screen_type = #{screenType}
  AND deleted = 0

SELECT screen_id
FROM tb_screen_person
WHERE year = #{year}
  AND town = #{town}
  AND deleted = 0

SELECT id, name, id_num, screen_type, is_new, is_screened, is_new_student,
       first_type, more_type, screen_time, sex, age, tel, nation, school_or_temple,
       classroom, height, weight, permanent_address, permanent_address_province,
       permanent_address_city, permanent_address_county, permanent_address_town,
       address, province, city, county, town, screen_point, screen_id, year
FROM tb_screen_person
WHERE deleted = 0
AND id_num = #{idNum}
AND year = #{year}
AND name LIKE #{name} || '%'
AND age = #{age}
AND sex = #{sex}
AND address LIKE #{address} || '%'
AND nation = #{nation} 
AND first_type = #{firstType}
AND screen_id LIKE #{screenId} || '%'
AND school_or_temple LIKE #{schoolOrTemple} || '%'
AND classroom LIKE #{classroom} || '%'

mapper.update:
UPDATE tb_screen_images
SET url = #{imageStr}
WHERE id = #{imageId} AND deleted = 0

